import copy, re, glob
ok_n = ko_n = 0
def ok(c, m, d=None):
    global ok_n, ko_n
    if c: ok_n += 1; print('  ✔ ' + m)
    else: ko_n += 1; print('  ✘ ' + m + ('' if d is None else ' ' + str(d)[:400]))
U = f'http://localhost:{PORT}/v2.html#'
S2 = copy.deepcopy(S)
# UX3 : plus aucune fenêtre du navigateur dans le code du site
reste = []
for f in glob.glob(str(ICI.parent / 'public' / 'js' / '**' / '*.js'), recursive=True):
    for i, l in enumerate(open(f, encoding='utf-8').read().split('\n')):
        if re.search(r'(^|[^.\w])(window\.)?(confirm|alert|prompt)\(', l) and not l.strip().startswith('//'): reste.append(f.split('/public/')[1] + ':' + str(i + 1))
ok(not reste, 'UX3 : aucune fenêtre confirm / alert / prompt du navigateur dans le code', reste)
