        r = await ev("(()=>{const f=document.querySelector('.dlg-b'); return {c:f.className, h:f.querySelector('h4').textContent, li:f.querySelectorAll('li').length, foc:document.activeElement.textContent}})()")
        ok('rouge' in r['c'] and r['h'] == 'À vérifier avant de valider' and r['li'] == 1 and r['foc'] == 'Annuler', 'UX3 : fenêtre rouge, titre, liste à puces, la main sur Annuler', r)
